NEW_FILES = {'zoo_keeper/core/crowd_barrier_forms.py': '"""What a steel crowd-control barricade is, in numbers: ONE place, no bpy.\n\nFactory roadmap 267, the walker\'s look review of 2026-10-20: arena_a02\'s four barriers -- Deli Counter volumes of\n3.0 x 0.8 x 1.2 m that built as plain boxes -- are to be "Crowd rails (a new model)", not the concrete jersey barrier.\nThis draws one panel of the interlocking barricade crowds are lined up behind at an arena\'s gates and a parade\'s kerb:\na welded tube frame on two flat feet, vertical pickets between its rails, hooks at one end that drop over the next\npanel\'s leg.\n\nREFERENCE, the common sizes as fabricators list them (not a standard\'s; no code governs a barricade\'s dimensions):\na panel about 7.5 ft long and 43 in tall on flat steel feet about 24 in long; a frame of 1-1/2 in tube with 1-1/4 in\nrails, 3/4 in tube pickets, about fourteen to a 7.5 ft panel, the bottom rail about 8 in off the ground; hot-dip\ngalvanised. The genome\'s defaults are those sizes and its ranges hold arena_a02\'s slot.\n  * `LEG_R`, `RAIL_R`, `PICKET_R`: the tubes\' radii, 1-1/2, 1-1/4 and 3/4 in across;\n  * `PICKET_CLEAR`: the clear between pickets, 5-1/4 in -- the clear of fourteen pickets in a 7.5 ft frame;\n  * `BOTTOM_Z`: the bottom rail\'s centre 8 in over the floor;\n  * `FOOT_W`, `FOOT_T`: 2 in flat bar, drawn 3/8 in thick where the steel is 1/4, so it holds a pixel a few metres out\n    (as the stoop railing\'s pickets and the fence\'s tension wire are drawn heavier than they are);\n  * `HOOK_R`, `HOOK_CLEAR`, `HOOK_DROP`: 5/8 in rod bent out and down, its opening just over a leg\'s width, so it\n    could drop over the next panel\'s leg.\n\nTHE FRAME is the module\'s own: X along the panel, the hooks at +X; Y across, the feet\'s length; Z up. Centre pivot, and\nthe extents are exactly the slot\'s (w, d, h): the -X foot\'s outer edge and the hooks\' outer face are the box\'s ends,\nthe feet are its depth, the feet\'s undersides its bottom and the legs\' capped tops its top.\n\nEVERY TUBE HAS EIGHT SIDES. Zoo\'s export keeps a fold under 50 degrees smooth (`geometry.SMOOTH_ANGLE_DEG`): eight\nsides fold at 45 and read round; six fold at 60 and read as hexagonal bar.\n\nNO FACE OF ONE PART LIES ON ANOTHER\'S, so `prims.coincident_pairs` reads none before Blender does. The pickets turn by\n`PICKET_PHASE` and the hooks\' arms by `HOOK_PHASE`, so no picket\'s facet is parallel to a leg\'s and no arm\'s to a\nrail\'s; a box\'s faces are axis-aligned and no tube\'s facet is. A TUBE END HIDDEN INSIDE ANOTHER MEMBER IS LEFT OPEN,\nand every such end is narrower than the member\'s inscribed radius (an eight-sided ring\'s flats are cos 22.5 = 0.924 of\nits corners), so no opening shows: a leg\'s foot inside its foot plate, a rail\'s ends inside the legs, a picket\'s ends on\nthe rails\' centre lines, a hook\'s arm inside its leg and its drop. What shows is closed: the legs\' tops are capped,\n`LEG_PROUD` over the top rail, and each hook\'s drop is capped at both ends.\n\nCOLLISION: the panel -- the frame\'s thickness, leg to leg, floor to top. The feet stay out of it: a 3/8 in plate is\nunder any step. Deli Counter writes its volume\'s own collider in the greybox the graders walk (arena_a02\'s is the\nconvex 3.0 x 0.8 x 1.2 box the barriers always were); this one is the module\'s, for a panel standing anywhere else.\n"""\nfrom __future__ import annotations\n\nimport math\n\nfrom . import prims\n\nIN = 0.0254\nLEG_R = round(0.75 * IN, 5)           # 1-1/2 in tube\nRAIL_R = round(0.625 * IN, 5)         # 1-1/4 in tube\nPICKET_R = round(0.375 * IN, 5)       # 3/4 in tube\nPICKET_CLEAR = round(5.25 * IN, 5)    # fourteen pickets to a 7.5 ft panel\nBOTTOM_Z = round(8 * IN, 4)           # the bottom rail\'s centre over the floor\nFOOT_W = round(2 * IN, 4)             # flat bar across X\nFOOT_T = round(0.375 * IN, 4)         # its thickness, drawn heavier than the 1/4 in steel\nHOOK_R = round(0.3125 * IN, 5)        # 5/8 in rod: the drop\nARM_R = round(HOOK_R * 0.9, 5)        # the arm, narrower than the drop\'s flats so its end hides in it\nHOOK_CLEAR = round(1.75 * IN, 4)      # the opening between the leg and the drop: over a 1-1/2 in leg\nHOOK_DROP = round(1.5 * IN, 4)        # how far the drop hangs below the arm\n#: the hooks\' arms over the bottom rail and under the top rail\nHOOK_INSET = 0.08\n#: a leg\'s capped top over the top rail\'s, so the two are never one plane\nLEG_PROUD = 0.01\n#: a leg\'s open foot inside its foot plate\nSINK = 0.004\nSIDES = 8\nPICKET_PHASE = math.pi / 16\nHOOK_PHASE = math.pi / 16\n#: inscribed / circumscribed radius of an eight-sided ring\nFLAT = math.cos(math.pi / SIDES)\nMAT = "steel"\nPART = "CrowdBarrier_Steel"\n\n\ndef _open(p, keep=()):\n    """``p`` with its two end caps (faces 0 and 1 of `prims.cyl` and `prims.rod`) dropped, but those in ``keep``."""\n    q = dict(p)\n    q["faces"] = [f for i, f in enumerate(p["faces"]) if i >= 2 or i in keep]\n    return q\n\n\ndef frame_x(w):\n    """``(x_lo_leg, x_hi_leg, x_drop)`` -- the two legs\' centres and the hooks\' drops\' -- for a panel ``w`` long.\n\n    The -X foot\'s outer edge is -w/2; the hooks\' drops\' outer faces are +w/2, `HOOK_CLEAR` clear of the +X leg."""\n    x_lo = -w / 2.0 + FOOT_W / 2.0\n    x_drop = w / 2.0 - HOOK_R\n    x_hi = x_drop - HOOK_R - HOOK_CLEAR - LEG_R\n    return x_lo, x_hi, x_drop\n\n\ndef picket_xs(x0, x1):\n    """Picket centres between the legs\' inner faces ``x0`` and ``x1``: as few as keep every clear gap at most\n    `PICKET_CLEAR`, the gaps equal."""\n    width = 2 * PICKET_R\n    span = x1 - x0\n    n = max(0, math.ceil((span - PICKET_CLEAR) / (width + PICKET_CLEAR) - 1e-9))\n    if n == 0:\n        return []\n    gap = (span - n * width) / (n + 1)\n    return [x0 + gap * (i + 1) + width * (i + 0.5) for i in range(n)]\n\n\ndef plan(w, d, h):\n    """The barricade for a slot of ``w`` x ``d`` x ``h`` (X along the panel, the hooks at +X): ``{prims, collision,\n    facts}``."""\n    w, d, h = float(w), float(d), float(h)\n    z0, z1 = -h / 2.0, h / 2.0\n    x_lo, x_hi, x_drop = frame_x(w)\n    z_top = z1 - LEG_PROUD - RAIL_R           # the top rail\'s centre\n    z_bot = z0 + BOTTOM_Z                     # the bottom rail\'s centre\n    # the frame stands, and its two hooks hang one above the other between its rails\n    if x_hi - LEG_R <= x_lo + LEG_R or z_top - HOOK_INSET - HOOK_DROP <= z_bot + HOOK_INSET + HOOK_R:\n        raise ValueError("a crowd barrier %.3f x %.3f x %.3f m cannot hold its frame" % (w, d, h))\n    if d < 2 * LEG_R:\n        raise ValueError("a crowd barrier %.4f m deep cannot stand its legs on its feet" % d)\n    out = []\n    # the two flat feet, the panel\'s depth long, under the legs\n    for x in (x_lo, x_hi):\n        out.append(prims.box(PART, MAT, (x - FOOT_W / 2, -d / 2, z0), (x + FOOT_W / 2, d / 2, z0 + FOOT_T)))\n    # the legs: open at the foot (inside the plate), capped at the top\n    for x in (x_lo, x_hi):\n        out.append(_open(prims.cyl(PART, MAT, (x, 0.0), LEG_R, z0 + FOOT_T - SINK, z1, segments=SIDES), keep=(1,)))\n    # the rails, leg centre to leg centre, both ends inside the legs\n    for z in (z_bot, z_top):\n        out.append(_open(prims.rod(PART, MAT, (x_lo, 0.0, z), (x_hi, 0.0, z), RAIL_R, segments=SIDES)))\n    # the pickets, rail centre to rail centre\n    xs = picket_xs(x_lo + LEG_R, x_hi - LEG_R)\n    for x in xs:\n        out.append(_open(prims.cyl(PART, MAT, (x, 0.0), PICKET_R, z_bot, z_top, segments=SIDES,\n                                   phase=PICKET_PHASE)))\n    # the hooks: an arm out of the +X leg into a drop that hangs below it\n    for z in (z_bot + HOOK_INSET, z_top - HOOK_INSET):\n        out.append(_open(prims.rod(PART, MAT, (x_hi, 0.0, z), (x_drop, 0.0, z), ARM_R, segments=SIDES,\n                                   phase=HOOK_PHASE)))\n        out.append(prims.cyl(PART, MAT, (x_drop, 0.0), HOOK_R, z - HOOK_DROP, z + HOOK_R, segments=SIDES))\n    boxes = [((x_lo - LEG_R, -LEG_R, z0), (x_hi + LEG_R, LEG_R, z1))]\n    out, boxes = prims.fit_exact(out, (-w / 2, -d / 2, z0), (w / 2, d / 2, z1), boxes)\n    facts = {"tris": prims.tri_count(out), "pickets": len(xs), "legs_x": [round(x_lo, 6), round(x_hi, 6)],\n             "rails_z": [round(z_bot, 6), round(z_top, 6)]}\n    return {"prims": out, "collision": boxes, "facts": facts}\n', 'zoo_keeper/recipes/crowd_barrier.py': '"""crowd_barrier recipe: a steel crowd-control barricade, one interlocking panel on its flat feet.\n\nFactory roadmap 267, the walker\'s look review of 2026-10-20: arena_a02\'s barriers are to be "Crowd rails (a new\nmodel)". `core.crowd_barrier_forms` lays it out in pure Python -- the reference sizes, the frame, why no two faces meet\nand why no open tube end shows -- and `bpylayer.prim_mesh` builds those lists vertex for vertex, so what its tests\nmeasure is what ships.\n\nOne material whatever the size: galvanised steel, in the genome\'s grey. Collision: the panel, as the plan gives it.\n"""\nfrom __future__ import annotations\n\nfrom ..bpylayer import prim_mesh\nfrom ..core import crowd_barrier_forms as F\n\n\ndef build(plan, streams, collection):\n    w = plan["dimensions"]["width"]\n    d = plan["dimensions"]["depth"]\n    h = plan["dimensions"]["height"]\n    got = F.plan(w, d, h)\n    mats = {F.MAT: (f"M_CrowdBarrier_{plan[\'material\']}", list(plan["color"]), plan["material"])}\n    objs = prim_mesh.build(got["prims"], collection, plan, streams.stream("wear"), mats, texel=1.2)\n    print(f"[crowd_barrier] {w:.3f} x {d:.3f} x {h:.3f} tris={got[\'facts\'][\'tris\']} "\n          f"pickets={got[\'facts\'][\'pickets\']}")\n    return {"objects": objs, "collision_boxes": got["collision"], "attachments": {},\n            "crowd_barrier": {"tris": got["facts"]["tris"], "pickets": got["facts"]["pickets"]}}\n', 'zoo_keeper/genome/species/crowd_barrier.json': '{\n  "species": "crowd_barrier",\n  "version": 1,\n  "license": {\n    "construction_knowledge": "CC0",\n    "notes": "Factory roadmap 267, the walker\'s look review of 2026-10-20 on arena_a02\'s four barrier volumes (3.0 x 0.8 x 1.2 m, built as boxes): \'Crowd rails (a new model)\', not the jersey barrier. REFERENCE: a hot-dip galvanised steel crowd-control barricade -- one interlocking panel of 1-1/2 in tube legs and 1-1/4 in rails with 3/4 in pickets, fourteen to a 7.5 ft panel, the bottom rail 8 in up, on two flat-bar feet, hooks at one end that drop over the next panel\'s leg. The defaults are the common fabricated sizes, 7.5 ft x 43 in on 24 in feet; the ranges hold arena_a02\'s slot (`core/crowd_barrier_forms.py`). One material. Collision: the panel; Deli Counter writes its volume\'s own collider in the greybox. BUILT: 412 tris at the default dims, 476 at arena_a02\'s, 508 at the largest corner (2026-10-20)."\n  },\n  "dimensions": {\n    "width": {\n      "min": 1.8,\n      "max": 3.2,\n      "default": 2.286\n    },\n    "depth": {\n      "min": 0.45,\n      "max": 0.9,\n      "default": 0.61\n    },\n    "height": {\n      "min": 0.95,\n      "max": 1.25,\n      "default": 1.092\n    }\n  },\n  "parts": [\n    "CrowdBarrier_Steel"\n  ],\n  "params": {},\n  "materials": {\n    "default": "metal_bare",\n    "options": [\n      "metal_bare"\n    ]\n  },\n  "styles": {\n    "default": {\n      "material": "metal_bare",\n      "color": [\n        0.6,\n        0.62,\n        0.63\n      ],\n      "wear": 0.15,\n      "bevel": 0.0\n    },\n    "delco": {\n      "material": "metal_bare",\n      "color": [\n        0.6,\n        0.62,\n        0.63\n      ],\n      "wear": 0.35,\n      "bevel": 0.0,\n      "ambient": 0.35\n    },\n    "center_city": {\n      "material": "metal_bare",\n      "color": [\n        0.6,\n        0.62,\n        0.63\n      ],\n      "wear": 0.122,\n      "bevel": 0.0,\n      "ambient": 0.15\n    },\n    "industrial_flats": {\n      "material": "metal_bare",\n      "color": [\n        0.55,\n        0.56,\n        0.56\n      ],\n      "wear": 0.57,\n      "bevel": 0.0,\n      "ambient": 0.45\n    },\n    "rockay": {\n      "material": "metal_bare",\n      "color": [\n        0.6,\n        0.62,\n        0.63\n      ],\n      "wear": 0.29,\n      "bevel": 0.0,\n      "ambient": 0.05\n    }\n  },\n  "budgets": {\n    "tris_lod0": 520\n  },\n  "attachments": [],\n  "collision": true,\n  "match_priority": 0,\n  "keywords": [\n    "crowd barrier",\n    "crowd control barrier",\n    "crowd barricade",\n    "bike rack barricade",\n    "crowd rail",\n    "police barricade",\n    "crowd_barrier"\n  ]\n}\n', 'tests/test_crowd_barrier.py': '"""crowd_barrier (1.118.0): a steel crowd-control barricade, one interlocking panel on its flat feet.\n\nFactory roadmap 267, the walker\'s look review of 2026-10-20: arena_a02\'s four barriers -- 3.0 x 0.8 x 1.2 m boxes --\nare to be "Crowd rails (a new model)". `core.crowd_barrier_forms` is the plan, drawn from a slot\'s box alone; the\nrecipe builds the same lists through `bpylayer.prim_mesh`. Pure: nothing here needs Blender. Every test here fails on\n1.117.0, which has no such species.\n"""\nimport itertools\nimport math\n\nimport pytest\n\nfrom zoo_keeper.core import crowd_barrier_forms as F\nfrom zoo_keeper.core import genome, kit, prims\n\nIN = 0.0254\n#: arena_a02\'s barrier volumes, as Deli Counter writes them (long side first, `prop_species.long_axis_first`)\nARENA = (3.0, 0.8, 1.2)\nSIZES = list(itertools.product((1.8, 2.0, 2.286, 2.5, 3.0, 3.2), (0.45, 0.61, 0.8, 0.9), (0.95, 1.092, 1.2, 1.25)))\n\n\ndef test_crowd_barrier_is_discovered_and_validates():\n    assert "crowd_barrier" in genome.list_species()\n    g = genome.load_species("crowd_barrier")\n    assert genome.validate_genome(g) == []\n    assert g["collision"] is True\n    assert g["parts"] == [F.PART]\n    assert g["materials"] == {"default": "metal_bare", "options": ["metal_bare"]}\n\n\ndef _arena_plan(material):\n    return kit.plan_kit({"building_id": "arena_a02", "slots": [{\n        "slot_id": "barrier_0", "role": "prop", "size_mod": "full", "style": 4, "material": material,\n        "species": "crowd_barrier", "kit_axis": "material",\n        "transform": {"translation": [-15.0, -6.0, 0.6], "rot_y": 0.0, "scale": [1.0, 1.0, 1.0]},\n        "fit": {"dims": list(ARENA), "pivot": "center", "openings": [], "collision": "convex"}}]},\n        theme="delco_1997", style=1)\n\n\ndef test_arena_a02s_barrier_plans_as_the_species():\n    """arena_a02\'s slot as Deli Counter 0.242.0 writes it -- in the species\' own kind, `metal_bare` -- plans as the\n    species at the theme the levels build in, with no fallback and no `_m` in its stem: the galvanised grey is the\n    genome\'s. The kit KEEPS a slot\'s known kind that the genome does not offer, as `dna.resolve_module_plan` says, so\n    the spec\'s old `metal` would have planned the `_mmetal` module, in the theme\'s metal pack: why Deli Counter\n    writes the species\' own kind (its `level_design._PROP_MATERIALS`, the dartboard\'s rule)."""\n    plan = _arena_plan("metal_bare")\n    assert plan["species_fallbacks"] == []\n    (m,) = plan["modules"]\n    assert m["species"] == "crowd_barrier"\n    assert m["stem"] == "prop_crowd_barrier_delco_1997_04_w300_d80_h120", m["stem"]\n    assert _arena_plan("metal")["modules"][0]["stem"].endswith("_mmetal")\n\n\ndef test_the_defaults_are_the_reference_panel():\n    g = genome.load_species("crowd_barrier")["dimensions"]\n    # 7.5 ft long, 43 in tall, on 24 in feet\n    assert math.isclose(g["width"]["default"], 90 * IN, abs_tol=1e-3)\n    assert math.isclose(g["height"]["default"], 43 * IN, abs_tol=1e-3)\n    assert math.isclose(g["depth"]["default"], 24 * IN, abs_tol=1e-3)\n    # 1-1/2 in legs, 1-1/4 in rails, 3/4 in pickets; fourteen pickets to the 7.5 ft panel\n    assert (round(2 * F.LEG_R / IN, 3), round(2 * F.RAIL_R / IN, 3), round(2 * F.PICKET_R / IN, 3)) == (1.5, 1.25, 0.75)\n    assert F.plan(g["width"]["default"], g["depth"]["default"], g["height"]["default"])["facts"]["pickets"] == 14\n    # and the genome\'s ranges hold arena_a02\'s slot\n    for v, k in zip(ARENA, ("width", "depth", "height")):\n        assert g[k]["min"] <= v <= g[k]["max"], (k, v)\n\n\n@pytest.mark.parametrize("w,d,h", SIZES)\ndef test_the_extents_are_exactly_the_slots(w, d, h):\n    lo, hi = prims.bounds(F.plan(w, d, h)["prims"])\n    for a, (want_lo, want_hi) in enumerate(((-w / 2, w / 2), (-d / 2, d / 2), (-h / 2, h / 2))):\n        assert math.isclose(lo[a], want_lo, abs_tol=1e-9) and math.isclose(hi[a], want_hi, abs_tol=1e-9)\n\n\n@pytest.mark.parametrize("w,d,h", SIZES)\ndef test_no_face_lies_on_another(w, d, h):\n    assert prims.coincident_pairs(F.plan(w, d, h)["prims"]) == []\n\n\ndef test_the_coincidence_check_can_see_a_pair():\n    """The control: a picket laid with its facet on a leg\'s, unturned, is a pair the probe reports."""\n    a = prims.cyl(F.PART, F.MAT, (0.0, 0.0), F.LEG_R, 0.0, 1.0, segments=F.SIDES)\n    b = prims.box(F.PART, F.MAT, (F.LEG_R * F.FLAT, -0.004, 0.2), (F.LEG_R * F.FLAT + 0.01, 0.004, 0.8))\n    b = prims.rotate_z(b, math.pi / F.SIDES, about=(0.0, 0.0))\n    assert prims.coincident_pairs([a, b])\n\n\ndef _boundary_loops(p):\n    """The open ends of a primitive: its edges used by one face, chained into loops."""\n    count = {}\n    for f in p["faces"]:\n        for a, b in zip(f, f[1:] + f[:1]):\n            k = (min(a, b), max(a, b))\n            count[k] = count.get(k, 0) + 1\n    nxt = {}\n    for (a, b), n in count.items():\n        if n == 1:\n            nxt.setdefault(a, []).append(b)\n            nxt.setdefault(b, []).append(a)\n    loops, seen = [], set()\n    for start in nxt:\n        if start in seen:\n            continue\n        loop, prev, cur = [start], None, start\n        seen.add(start)\n        while True:\n            cand = [v for v in nxt[cur] if v != prev]\n            if not cand or cand[0] == start:\n                break\n            prev, cur = cur, cand[0]\n            if cur in seen:\n                break\n            seen.add(cur)\n            loop.append(cur)\n        loops.append(loop)\n    return loops\n\n\ndef _half_spaces(p):\n    """``p`` as a convex solid: each face\'s plane and each open end\'s, every normal away from its centroid."""\n    vs = p["verts"]\n    c = [sum(v[a] for v in vs) / len(vs) for a in range(3)]\n    out = []\n    for loop in [list(f) for f in p["faces"]] + _boundary_loops(p):\n        pts = [vs[i] for i in loop]\n        n = [0.0, 0.0, 0.0]\n        for (x0, y0, z0), (x1, y1, z1) in zip(pts, pts[1:] + pts[:1]):\n            n[0] += (y0 - y1) * (z0 + z1)\n            n[1] += (z0 - z1) * (x0 + x1)\n            n[2] += (x0 - x1) * (y0 + y1)\n        ln = math.sqrt(sum(x * x for x in n))\n        n = [x / ln for x in n]\n        dd = sum(n[a] * pts[0][a] for a in range(3))\n        if sum(n[a] * c[a] for a in range(3)) > dd:\n            n, dd = [-x for x in n], -dd\n        out.append((n, dd))\n    return out\n\n\n@pytest.mark.parametrize("w,d,h", [ARENA, (2.286, 0.61, 1.092), (1.8, 0.45, 0.95), (3.2, 0.9, 1.25)])\ndef test_no_open_end_shows(w, d, h):\n    """Every tube end left open lies strictly inside another member: a leg\'s foot in its plate, a rail\'s ends in the\n    legs, a picket\'s on the rails\' centre lines, a hook\'s arm in its leg and its drop."""\n    ps = F.plan(w, d, h)["prims"]\n    solids = [_half_spaces(p) for p in ps]\n    opened = 0\n    for i, p in enumerate(ps):\n        for loop in _boundary_loops(p):\n            opened += 1\n            for vi in loop:\n                v = p["verts"][vi]\n                assert any(all(sum(n[a] * v[a] for a in range(3)) - dd < -1e-7 for n, dd in solids[j])\n                           for j in range(len(ps)) if j != i), (i, v)\n    # two legs, two rails (both ends), each picket (both ends), two arms (both ends)\n    assert opened == 2 + 4 + 2 * F.plan(w, d, h)["facts"]["pickets"] + 4\n\n\ndef test_an_open_end_is_narrower_than_what_hides_it():\n    assert F.RAIL_R < F.LEG_R * F.FLAT and F.PICKET_R < F.RAIL_R * F.FLAT and F.ARM_R < F.HOOK_R * F.FLAT\n    assert F.LEG_R < F.FOOT_W / 2 and 0 < F.SINK < F.FOOT_T\n\n\n@pytest.mark.parametrize("w,d,h", SIZES)\ndef test_every_clear_gap_between_pickets_is_equal_and_inside_the_clear(w, d, h):\n    x_lo, x_hi, _x_drop = F.frame_x(w)\n    x0, x1 = x_lo + F.LEG_R, x_hi - F.LEG_R\n    xs = F.picket_xs(x0, x1)\n    edges = [x0] + [e for xc in xs for e in (xc - F.PICKET_R, xc + F.PICKET_R)] + [x1]\n    gaps = [b - a for a, b in zip(edges[::2], edges[1::2])]\n    assert max(gaps) <= F.PICKET_CLEAR + 1e-9 and min(gaps) > 0.0\n    assert max(gaps) - min(gaps) < 1e-9\n\n\ndef test_the_hooks_would_drop_over_the_next_panels_leg():\n    x_lo, x_hi, x_drop = F.frame_x(ARENA[0])\n    assert F.HOOK_CLEAR > 2 * F.LEG_R\n    # their opening, the +X leg\'s face to the drop\'s inner face, is HOOK_CLEAR\n    assert math.isclose((x_drop - F.HOOK_R) - (x_hi + F.LEG_R), F.HOOK_CLEAR, abs_tol=1e-9)\n    assert x_drop > x_hi > x_lo\n\n\ndef test_one_material_one_part_one_submission_inside_the_budget():\n    budget = genome.load_species("crowd_barrier")["budgets"]["tris_lod0"]\n    worst = 0\n    for w, d, h in SIZES:\n        got = F.plan(w, d, h)\n        assert {p["mat"] for p in got["prims"]} == {F.MAT}\n        assert {p["part"] for p in got["prims"]} == {F.PART}\n        worst = max(worst, got["facts"]["tris"])\n    assert worst <= budget, (worst, budget)\n\n\n@pytest.mark.parametrize("w,d,h", [ARENA, (1.8, 0.45, 0.95), (3.2, 0.9, 1.25)])\ndef test_the_collision_is_the_panel(w, d, h):\n    (lo, hi), = F.plan(w, d, h)["collision"]\n    assert math.isclose(lo[2], -h / 2) and math.isclose(hi[2], h / 2)\n    assert math.isclose(hi[1] - lo[1], 2 * F.LEG_R, abs_tol=1e-9)\n    assert -w / 2 <= lo[0] < hi[0] <= w / 2\n\n\ndef test_a_box_too_small_for_the_frame_is_refused():\n    with pytest.raises(ValueError):\n        F.plan(0.12, 0.6, 1.1)\n    with pytest.raises(ValueError):\n        F.plan(2.3, 0.6, 0.3)\n    with pytest.raises(ValueError):\n        F.plan(2.3, 0.02, 1.1)\n'}
CHANGELOG = '## [1.118.0] - a steel crowd-control barricade, one interlocking panel on its flat feet: crowd_barrier\n\n**The factory\'s roadmap 267, the walker\'s look review of 2026-10-20**: arena_a02\'s four barrier volumes -- 3.0 x 0.8 x\n1.2 m, built as plain boxes -- are to be "Crowd rails (a new model)", not the concrete jersey barrier. Deli Counter\n0.242.0 routes the word `barrier` to this species and writes those volumes in its own kind.\n\n- **`crowd_barrier`**, laid out in pure Python by `core/crowd_barrier_forms.py` and built vertex for vertex through\n  `bpylayer.prim_mesh` (the stoop railing\'s pattern), from the slot\'s box alone: two flat-bar feet the panel\'s depth\n  long; a leg on each, capped at the top; a bottom and a top rail between the legs; pickets between the rails; and at\n  +X two hooks -- an arm out of the leg into a drop hanging below it, its opening just over a leg\'s width -- so a panel\n  could hook over the next one\'s leg.\n- **The numbers are the common fabricated sizes** (no code governs a barricade): 1-1/2 in tube legs, 1-1/4 in rails,\n  3/4 in pickets at 5-1/4 in clear, fourteen to a 7.5 ft panel; the bottom rail 8 in up; 2 in flat-bar feet drawn 3/8\n  in thick so they hold a pixel; 5/8 in rod hooks. The genome\'s defaults are the common panel, 7.5 ft x 43 in on 24 in\n  feet; its ranges, 1.8-3.2 x 0.45-0.9 x 0.95-1.25 m, hold arena_a02\'s slot.\n- **Every tube has eight sides.** Zoo\'s export keeps a fold under 50 degrees smooth (`geometry.SMOOTH_ANGLE_DEG`), so\n  eight sides, folding at 45, read round; six would read as hexagonal bar.\n- **No face of one part lies on another\'s, and no open end shows.** The pickets and the hooks\' arms turn a sixteenth\n  of a circle, so no facet of theirs is parallel to a leg\'s or a rail\'s. A tube end hidden inside another member is\n  left open and is narrower than that member\'s flats -- a leg\'s foot in its plate, a rail\'s ends in the legs, a\n  picket\'s on the rails\' centre lines, an arm in its leg and its drop -- and what shows is closed: the legs\' tops,\n  capped 1 cm over the top rail, and each drop, capped at both ends.\n- **One material, one part, one submission:** hot-dip galvanised steel, `metal_bare` in the chain-link fence\'s grey\n  (0.60 / 0.62 / 0.63, worn by theme). **Collision:** the panel, the frame\'s thickness from leg to leg and floor to\n  top; the feet stay out of it. Deli Counter writes its volume\'s own collider in the greybox the graders walk --\n  arena_a02\'s is the convex 3.0 x 0.8 x 1.2 box the barriers always were -- so their cover and pathing do not move.\n- **A slot\'s kind decides the module.** The kit keeps a slot\'s known kind that the genome does not offer\n  (`dna.resolve_module_plan`), so a slot in `metal` plans the `_mmetal` module in the theme\'s metal pack. Deli Counter\n  0.242.0 writes arena_a02\'s barriers in the species\' own `metal_bare` (its `level_design._PROP_MATERIALS`, the\n  dartboard\'s rule), and the stem carries no `_m`.\n\n**Measured, Blender 5.1.1** (the factory\'s `patches/zoo_crowd_barrier/`):\n\n- `blender -b --python tools/coplanar_census.py -- --species crowd_barrier bollard`: the barricade\'s three corners\n  build at 348 / 412 / 508 tris with 0 pairs, first run; the bollard, the control that the census sees a pair, its\n  known 2 / 2 / 1. "6 builds, 3 with coincident pairs, 0 that did not build". `CENSUS_BUILDS` 411 -> 414. 520 is the\n  genome\'s budget, inside the standard\'s small-clutter class, 300 to 1,500 (the factory\'s\n  `docs/reference/MODERN_LOW_POLY_ASSET_STANDARD.md`, section 1).\n- arena_a02\'s four barrier slots through `zoo_cli --build-kit`, shaped as Deli Counter 0.242.0 writes them:\n  `prop_crowd_barrier_delco_1997_04_w300_d80_h120.glb` x4 PASS -- one visual mesh, one primitive, one material\n  (`M_CrowdBarrier_metal_bare`), 476 tris, its bounds the slot\'s exactly, and its panel collider.\n\n### Tests\n- `tests/test_crowd_barrier.py` (new): the genome validates and plans at arena_a02\'s slot with no fallback and the\n  stem above; the defaults are the reference panel and plan its fourteen pickets; the extents are the slot\'s exactly\n  and no face lies on another over 96 sizes, the probe\'s control seeing a planted pair; every open end\'s every vertex\n  lies strictly inside another member, at four sizes; the clear gaps are equal and inside 5-1/4 in; the hooks\' opening\n  holds a leg; one material and one part inside the budget at every size; the collision is the panel; a box too small\n  for the frame is refused. Every one fails on 1.117.0, which has no such species.\n- `tests/test_coincident_faces.py`: the census\'s record and `CENSUS_BUILDS`; `tests/test_material_options_closed.py`:\n  `crowd_barrier` among the galvanised species (`BARE`).\n\n**Suite:** 6,348 passed, 491 skipped, 1 xfailed in 6 min 5 s in the proven clone, where 1.117.0\'s clone passed 6,040 with 490 skipped (the factory\'s `patches/zoo_booth_marks/suite_clone.out.txt`; 27 tests skip in a scratch clone): the new file\'s 303, the five material checks every genome gets, and one skip more, `test_recipe_that_builds_materials_reads_its_genome[crowd_barrier]`, "builds no materials" -- it sees only a direct `make_material` call, and this recipe builds through `prim_mesh` as the stoop railing\'s does. Of the tests that name the species, 308 pass and that one skips.\n\n'
OLD_VERSION, NEW_VERSION = '1.117.0', '1.118.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
